--- top-level keys: ['config', 'data', 'mark', 'encoding', 'height', 'params', 'title', 'transform', 'width', '$schema']
--- data url: https://cdn.jsdelivr.net/npm/vega-datasets@v3.2.1/data/population.json
--- mark: {'type': 'bar'}
--- params: [
  {
    "name": "year",
    "bind": {
      "input": "select",
      "options": [
        1850,
        1860,
        1870,
        1880,
        1900,
        1910,
        1920,
        1930,
        1940,
        1950,
        1960,
        1970,
        1980,
        1990,
        2000
      ],
      "name": "Year"
    },
    "value": 1980
  }
]
--- transforms: [
  {
    "filter": "datum.year == year"
  },
  {
    "calculate": "datum.sex === 1 ? -datum.people : datum.people",
    "as": "signed_people"
  }
]
--- x enc: {
  "axis": {
    "format": "s",
    "labelExpr": "format(abs(datum.value), \"s\")"
  },
  "field": "signed_people",
  "title": "Population",
  "type": "quantitative"
}
--- y enc: {
  "field": "age",
  "sort": "descending",
  "title": "Age",
  "type": "ordinal"
}
--- color enc: {
  "field": "sex",
  "legend": {
    "labelExpr": "datum.value == 1 ? \"Male\" : \"Female\"",
    "title": "Sex"
  },
  "scale": {
    "domain": [
      1,
      2
    ],
    "range": [
      "steelblue",
      "salmon"
    ]
  },
  "type": "nominal"
}
